import React, { useEffect, useState } from "react";
import currencyData from "./currency.json";
import LineGraph from "./LineGraph";
import image from "./assets/convert.png";

const App = () => {
  const [countryName, setCountryName] = useState("");
  const [selectedCurrency, setSelectedCurrency] = useState("INR");
  const [convertCurrency, setConvertCurrency] = useState("");
  const [fetchedData, setFetchedData] = useState({});
  const [conversionrate, setConversionrate] = useState(0);
  const [amount, setAmount] = useState(0);
  const [graphData, setGraphData] = useState([]);
  const [flag, setFlag] = useState("");

  useEffect(() => {
    const fetchIp = async () => {
      try {
        const response = await fetch("https://api.ipify.org?format=json");
        const data = await response.json();
        const ipAddress = data.ip;

        try {
          const response = await fetch(
            `http://api.ipstack.com/${ipAddress}?access_key=${import.meta.env.VITE_IPSTACK_API_KEY}`
          );
          if (!response.ok) {
            throw new Error("Network response was not ok");
          }
          const result = await response.json();
          setCountryName(result.country_name);
          setFlag(result.location.country_flag);

          const currency = currencyData.currencies.find(
            (item) => item.country === result.country_name
          );
          if (currency) {
            setSelectedCurrency(currency.code);
          }
        } catch (error) {
          console.error("Error fetching country data:", error.message);
        }
      } catch (error) {
        console.error("Error fetching IP address:", error);
      }
    };

    fetchIp();
  }, []);

  const handleCurrencyChange = (event) => {
    setSelectedCurrency(event.target.value);
  };
  const handleSecondCurrencyChange = (event) => {
    setConvertCurrency(event.target.value);
  };

  useEffect(() => {
    const currencyConversion = async () => {
      if (convertCurrency === "" || selectedCurrency === "") return;
      try {
        const response = await fetch(
          `https://api.exchangeratesapi.io/v1/latest?access_key=${import.meta.env.VITE_EXCHANGE_RATE_API_KEY}&symbols=${selectedCurrency},${convertCurrency}`
        );
        if (!response.ok) {
          throw new Error("Network response was not ok");
        }
        const result = await response.json();
        const rate =
          result.rates[convertCurrency] / result.rates[selectedCurrency];
        setConversionrate(rate);
      } catch (error) {
        console.error("Error fetching conversion data:", error.message);
      }

      function getLastSixMonthsSameDay() {
        const today = new Date();
        const dayOfMonth = today.getDate();
        const dates = [];

        for (let i = 0; i < 12; i++) {
          const date = new Date(
            today.getFullYear(),
            today.getMonth() - i,
            dayOfMonth
          );
          if (date.getDate() !== dayOfMonth) {
            date.setDate(0);
          }
          const formattedDate = date.toISOString().split("T")[0];
          dates.push(formattedDate);
        }

        return dates.reverse();
      }

      const datesArray = getLastSixMonthsSameDay();
      let prices = [];

      for (const date of datesArray) {
        const response = await fetch(
          `https://api.exchangeratesapi.io/v1/${date}?access_key=${EXCHANGE_RATE_API_KEY}&symbols=${selectedCurrency},${convertCurrency}`
        );
        if (!response.ok) {
          throw new Error("Network response was not ok");
        }
        const result = await response.json();
        const ratePrices =
          result.rates[convertCurrency] / result.rates[selectedCurrency];
        prices.push(ratePrices);
      }

      setGraphData(
        datesArray.map((date, index) => ({
          date,
          price: prices[index],
        }))
      );
    };

    currencyConversion();
  }, [selectedCurrency, convertCurrency]);

  return (
    <div className="bg-gray-900 text-white min-h-screen flex flex-col items-center p-6">
      <div className="text-center mb-6">
        <div className="flex">
        <h2 className="text-4xl font-bold">
          Your Country: {countryName || "Loading..."}
        </h2>
        {flag && (
          <img src={flag} className="w-12 h-10 mt-2" alt="Country Flag" />
        )}
        </div>
        <div className="text-sm text-gray-400 mt-2">
          (Live location fetched from{" "}
          <a
            href="https://ipstack.com/"
            className="underline text-blue-400"
            target="_blank"
            rel="noopener noreferrer"
          >
            IPStack API
          </a>
          )
        </div>
      </div>

      <div className="bg-gray-800 p-6 rounded-lg shadow-lg w-full max-w-4xl">
        <div className="flex gap-4 justify-center mb-6">
          <select
            value={selectedCurrency}
            onChange={handleCurrencyChange}
            className="p-3 rounded-md bg-gray-700 text-white border border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            {currencyData.currencies.map((currency, index) => (
              <option key={index} value={currency.code}>
                {currency.code}
              </option>
            ))}
          </select>
          <select
            onChange={handleSecondCurrencyChange}
            className="p-3 rounded-md bg-gray-700 text-white border border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            <option value="">Select the currency</option>
            {currencyData.currencies.map((currency, index) => (
              <option key={index} value={currency.code}>
                {currency.code}
              </option>
            ))}
          </select>
        </div>

        <div className="flex items-center justify-center mb-6">
          <input
            type="number"
            placeholder="Enter amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="p-3 w-48 rounded-md bg-gray-700 text-white border border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <div className="ml-4 text-xl font-semibold">{selectedCurrency}</div>
          <img src={image} className="w-8 h-8 mx-4" alt="Currency converter" />
          <div className="text-2xl font-bold">
            {(conversionrate * amount).toFixed(2)} {convertCurrency}
          </div>
        </div>

        <div className="text-lg text-gray-400 text-center mb-6">
          *1 {selectedCurrency} = {conversionrate.toFixed(4)} {convertCurrency}
        </div>

        <div className="text-center mt-6">
          <h1 className="text-xl font-semibold">Prices Over Time</h1>
          <LineGraph data={graphData} />
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from "react";

const LineGraph = ({ data }) => {
  const canvasRef = useRef(null);
  const [hoverData, setHoverData] = useState(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    // Set canvas dimensions
    canvas.width = 800;
    canvas.height = 400;

    // Define margins and graph area
    const margin = 50;
    const width = canvas.width - 2 * margin;
    const height = canvas.height - 2 * margin;

    // Get data values
    const labels = data.map((item) => item.date);
    const prices = data.map((item) => item.price);

    // Calculate the scaling factor
    const maxPrice = Math.max(...prices);
    const minPrice = Math.min(...prices);

    // Helper function to get x and y positions
    const getX = (index) => margin + (index / (prices.length - 1)) * width;
    const getY = (price) =>
      margin + height - ((price - minPrice) / (maxPrice - minPrice)) * height;

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Set background color for dark theme
    ctx.fillStyle = "#1a202c"; // Dark gray background
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw axes
    ctx.strokeStyle = "#E2E8F0"; // Light color for axis lines (contrast with dark background)
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(margin, margin);
    ctx.lineTo(margin, canvas.height - margin);
    ctx.lineTo(canvas.width - margin, canvas.height - margin);
    ctx.stroke();

    // Plot the line graph
    ctx.strokeStyle = "rgba(75, 192, 192, 1)"; // Light teal color for the graph line
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(getX(0), getY(prices[0]));

    prices.forEach((price, index) => {
      ctx.lineTo(getX(index), getY(price));
    });
    ctx.stroke();

    // Draw data points
    ctx.fillStyle = "rgba(75, 192, 192, 1)"; // Light teal color for points
    prices.forEach((price, index) => {
      ctx.beginPath();
      ctx.arc(getX(index), getY(price), 4, 0, 2 * Math.PI);
      ctx.fill();
    });

    // Add labels for x-axis (dates)
    // Helper function to format date as MM/YY
    const formatDate = (dateString) => {
      const date = new Date(dateString);
      const month = String(date.getMonth() + 1).padStart(2, "0"); // Get month (1-based)
      const year = String(date.getFullYear()).slice(-2); // Get last 2 digits of year
      return `${month}/${year}`;
    };

    // Add labels for x-axis (formatted dates)
    ctx.fillStyle = "#E2E8F0"; // Light color for labels
    ctx.font = "12px Arial";
    labels.forEach((label, index) => {
      const x = getX(index);
      const formattedDate = formatDate(label);
      ctx.fillText(formattedDate, x - 20, canvas.height - margin + 20);
    });

    // Add labels for y-axis (prices)
    ctx.fillText(`Min: ${minPrice}`, margin - 40, canvas.height - margin);
    ctx.fillText(`Max: ${maxPrice}`, margin - 40, margin);

    // Mouse move event to handle hover effect
    const handleMouseMove = (event) => {
      const rect = canvas.getBoundingClientRect();
      const mouseX = event.clientX - rect.left;
      const mouseY = event.clientY - rect.top;

      // Check if the mouse is close to any data point
      prices.forEach((price, index) => {
        const x = getX(index);
        const y = getY(price);
        const radius = 6;

        // Check if the mouse is within the point's radius
        if (
          mouseX >= x - radius &&
          mouseX <= x + radius &&
          mouseY >= y - radius &&
          mouseY <= y + radius
        ) {
          setHoverData({ x, y, price });
        } else {
          setHoverData(null);
        }
      });
    };

    // Mouse out event to hide tooltip when the mouse leaves the canvas
    const handleMouseOut = () => {
      setHoverData(null);
    };

    canvas.addEventListener("mousemove", handleMouseMove);
    canvas.addEventListener("mouseout", handleMouseOut);

    // Cleanup event listeners
    return () => {
      canvas.removeEventListener("mousemove", handleMouseMove);
      canvas.removeEventListener("mouseout", handleMouseOut);
    };
  }, [data]);

  return (
    <div style={{ position: "relative" }}>
      <canvas
        ref={canvasRef}
        style={{
          display: "block",
          margin: "0 auto",
        }}
      />
      {hoverData && (
        <div
          style={{
            position: "absolute",
            top: hoverData.y - 30,
            left: hoverData.x + 10,
            backgroundColor: "rgba(0, 0, 0, 0.7)", // Dark background for tooltip
            color: "#fff",
            padding: "5px",
            borderRadius: "4px",
            pointerEvents: "none",
            fontSize: "14px", // Slightly smaller font for tooltip
          }}
        >
          Price: {hoverData.price}
        </div>
      )}
    </div>
  );
};

export default LineGraph;
